#define main legacy_main
#include "../mergeVS-cuda/main.cu"
#undef main
#define reference study_reference
#define save_blocks_ref study_save_blocks_ref
#include "study_oracle.h"
#undef reference
#undef save_blocks_ref
#include <vector>
#include <filesystem>
#include <fstream>
#include <algorithm>
std::vector<int>readints(std::filesystem::path p){std::ifstream in(p,std::ios::binary);std::vector<char>b((std::istreambuf_iterator<char>(in)),{});std::vector<int>a(b.size()/4);memcpy(a.data(),b.data(),b.size());return a;}
struct StudyFixture{int B,H,R,M,N,V,S,C;std::vector<int>input[6];int*di[6];int*dout[2][4];std::vector<int>gold[2][4];StudyFixture(const std::vector<int>&a,size_t&pos){B=a[pos++];H=a[pos++];R=a[pos++];M=a[pos++];N=a[pos++];V=a[pos++];S=a[pos++];C=a[pos++];int ns[]={B,B,B*H*V,B*H*S,H,H};for(int k=0;k<6;k++){input[k]=std::vector<int>(a.begin()+pos,a.begin()+pos+ns[k]);pos+=ns[k];cudaMalloc(&di[k],ns[k]*4);cudaMemcpy(di[k],input[k].data(),ns[k]*4,cudaMemcpyHostToDevice);}int lens[]={B*H*R,B*H*R*S,B*H*R,B*H*R*V};for(int mode=0;mode<2;mode++){for(int k=0;k<4;k++){gold[mode][k].assign(lens[k]+17,-777777);std::fill_n(gold[mode][k].begin(),lens[k],0);cudaMalloc(&dout[mode][k],(lens[k]+17)*4);cudaMemcpy(dout[mode][k],gold[mode][k].data(),(lens[k]+17)*4,cudaMemcpyHostToDevice);}study_reference(input[0].data(),input[1].data(),input[2].data(),input[3].data(),input[4].data(),input[5].data(),gold[mode][0].data(),gold[mode][1].data(),gold[mode][2].data(),gold[mode][3].data(),B,H,R,M,N,V,S,mode==0);}}void reset(){for(int mode=0;mode<2;mode++)for(int k=0;k<4;k++){std::vector<int>z(gold[mode][k].size(),-777777);std::fill_n(z.begin(),z.size()-17,0);cudaMemcpy(dout[mode][k],z.data(),z.size()*4,cudaMemcpyHostToDevice);}}void execute(int mode){launch(dout[mode][0],dout[mode][1],dout[mode][2],dout[mode][3],di[0],di[1],di[2],di[3],di[4],di[5],C,M,N,mode==0,B,H,S,V);}};
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):20;auto dir=std::filesystem::path(__FILE__).parent_path();auto prefix=readints(dir/"fixture_bits.bin"),expected=readints(dir/"expected_metadata.bin");size_t pos=0;std::vector<StudyFixture>fs;for(int k=0;k<2;k++)fs.emplace_back(prefix,pos);std::vector<int>cpu;for(auto&f:fs)for(int mode=0;mode<2;mode++)for(auto&a:f.gold[mode])cpu.insert(cpu.end(),a.begin(),a.end());printf("CPU_REFERENCE_ORACLE_MATCH %s values=%zu\n",cpu==expected?"true":"false",cpu.size());if(cpu!=expected||pos!=prefix.size())return 2;for(auto&f:fs)for(int mode=0;mode<2;mode++)f.execute(mode);cudaDeviceSynchronize();for(int t=1;t<=5;t++){for(auto&f:fs)f.reset();cudaDeviceSynchronize();double times[4],total=0;for(int z=0;z<2;z++)for(int mode=0;mode<2;mode++){cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int k=0;k<rep;k++)fs[z].execute(mode);cudaDeviceSynchronize();times[2*z+mode]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/rep;total+=times[2*z+mode];}std::vector<int>got;for(auto&f:fs)for(int mode=0;mode<2;mode++)for(int k=0;k<4;k++){std::vector<int>a(f.gold[mode][k].size());cudaMemcpy(a.data(),f.dout[mode][k],a.size()*4,cudaMemcpyDeviceToHost);got.insert(got.end(),a.begin(),a.end());}bool ok=cudaGetLastError()==cudaSuccess&&got==expected;int err=0;for(size_t i=0;i<got.size();i++)err=std::max(err,abs(got[i]-expected[i]));auto artifact=prefix;artifact.insert(artifact.end(),got.begin(),got.end());std::string file=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(t)+".bin";FILE*fp=fopen(file.c_str(),"wb");fwrite(artifact.data(),4,artifact.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":null,\"timing_region\":\"sum4_vertical_slash_metadata_kernel_only\",\"jit_excluded\":true,\"internal_repeats\":%d,\"per_path_times_seconds\":[%.17g,%.17g,%.17g,%.17g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",t,total,ok?"true":"false",got.size(),err,rep,times[0],times[1],times[2],times[3],file.c_str(),artifact.size());}}
